package com.aistock.market.marketrefs;
import com.aistock.common.*;import com.aistock.common.marketrefs.MarketReferenceRecords.*;import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class MarketVersionReferenceClientTest {
 final String V="11111111-1111-1111-1111-111111111111";HttpServer server;AtomicReference<String> body=new AtomicReference<>();AtomicInteger status=new AtomicInteger(200),calls=new AtomicInteger(),delay=new AtomicInteger();AtomicReference<String> cookie=new AtomicReference<>(),token=new AtomicReference<>();ObjectMapper mapper=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 @BeforeEach void init()throws Exception{body.set(mapper.writeValueAsString(ApiResponse.success(new OwnerResult("prediction",V,Instant.parse("2026-10-28T00:00:00Z"),"COMPLETE",null,List.of(new Group("rows","records","COMPLETE","0",null))),"t")));server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{calls.incrementAndGet();cookie.set(e.getRequestHeaders().getFirst("Cookie"));token.set(e.getRequestHeaders().getFirst("X-Service-Token"));byte[] bytes=body.get().getBytes(java.nio.charset.StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","application/json");e.getResponseHeaders().set("Location","/redirected");e.sendResponseHeaders(status.get(),delay.get()>0?0:bytes.length);try{if(delay.get()>0)Thread.sleep(delay.get());e.getResponseBody().write(bytes);}catch(Exception ignored){}finally{e.close();}});server.start();}
 @AfterEach void stop(){server.stop(0);}
 MarketVersionReferenceClient client(Duration timeout){String url="http://127.0.0.1:"+server.getAddress().getPort();return new MarketVersionReferenceClient(Map.of("prediction",url,"scheduler",url,"notification",url),"test-service",mapper,timeout);}
 @Test void oneInternalGetSendsOnlyServiceToken(){assertEquals("COMPLETE",client(Duration.ofSeconds(2)).read("prediction",V).state());assertEquals(1,calls.get());assertNull(cookie.get());assertEquals("test-service",token.get());}
 @Test void wrongIdentityNumericCountAndRedirectNeverBecomeZero(){var client=client(Duration.ofSeconds(2));String original=body.get();for(String wrong:List.of(original.replace("prediction","scheduler"),original.replace(V,"22222222-2222-2222-2222-222222222222"),original.replace("\"rows\":\"0\"","\"rows\":0"))){body.set(wrong);assertEquals("UNKNOWN",client.read("prediction",V).state());}body.set(original);status.set(302);assertEquals("UNKNOWN",client.read("prediction",V).state());assertEquals(4,calls.get());}
 @Test void boundsWholeBodyAndAcceptsExactByteLimit(){var client=client(Duration.ofSeconds(2));String original=body.get();int bytes=original.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;body.set(original+" ".repeat(65536-bytes));assertEquals("COMPLETE",client.read("prediction",V).state());body.set(body.get()+" ");assertEquals("UNKNOWN",client.read("prediction",V).state());}
 @Test void headerArrivalDoesNotBypassWholeBodyDeadline(){delay.set(700);long start=System.nanoTime();assertEquals("UNKNOWN",client(Duration.ofMillis(150)).read("prediction",V).state());assertTrue((System.nanoTime()-start)/1_000_000<2000);assertEquals(1,calls.get());}
}
